<?php use App\Support\App;App::requireAdmin();$rows=App::db()->query('SELECT * FROM products ORDER BY sort_order,id DESC')->fetchAll();$title='Admin Products';require __DIR__.'/../layouts/head.php';require __DIR__.'/../components/app_start.php';?><div class="flex flex-col sm:flex-row sm:items-end justify-between gap-4"><div><h1 class="page-title">Products</h1><p class="page-sub">Kelola katalog dan sinkronisasi layanan provider.</p></div><button class="btn btn-dark" onclick="imp()"><i data-lucide="refresh-cw"></i>Import CeirGo</button></div><div class="saas-card mt-6 overflow-auto"><table class="w-full text-sm min-w-[560px]"><thead><tr><th>Product</th><th>Provider</th><th>CEIR</th><th>Status</th></tr></thead><tbody><?php foreach($rows as $p):?><tr class="border-t" style="border-color:var(--line)"><td class="font-semibold"><?=htmlspecialchars($p['name'])?></td><td><?=htmlspecialchars($p['provider_type'])?></td><td><span class="badge"><?=!empty($p['ceir_check_enabled'])?'ON':'OFF'?></span></td><td><span class="badge"><?=$p['is_active']?'ACTIVE':'OFF'?></span></td></tr><?php endforeach?></tbody></table></div><script>async function imp(){let r=await fetch('/api/admin/products/import-ceirgo',{method:'POST',headers:{'X-CSRF-Token':'<?=App::csrf()?>'}}),j=await r.json();Swal.fire(j.ok?'Import complete':'Import failed',j.message||'Provider synchronization finished',j.ok?'success':'error')}</script><?php require __DIR__.'/../components/app_end.php';require __DIR__.'/../layouts/foot.php';?>